import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutterfire_gen_annotation/flutterfire_gen_annotation.dart';

part 'todo.flutterfire_gen.dart';

@FirestoreDocument(path: 'todos/{todoId}')
class Todo {
  const Todo({required this.title, required this.isCompleted, this.createdAt, this.updatedAt});
  final String title;
  @ReadDefault(false)
  @CreateDefault(false)
  final bool isCompleted;
  @alwaysUseFieldValueServerTimestampWhenCreating
  final DateTime? createdAt;
  @alwaysUseFieldValueServerTimestampWhenCreating
  @alwaysUseFieldValueServerTimestampWhenUpdating
  final DateTime? updatedAt;
}

// After running build_runner, use TodoQuery to fetch or add documents.
